import {verifiedFetch} from '@github-ui/verified-fetch'
import {InfoIcon} from '@primer/octicons-react'
import {Banner, Link} from '@primer/react'
import {useEffect, useRef, useState} from 'react'
import type {
  BannerAnalytics,
  BannerSegment,
  TransactionalMessageBanner as TransactionalMessageBannerType,
} from '@github-ui/code-view-types'
import styles from './TransactionalMessageBanner.module.css'

export interface TransactionalMessageBannerProps {
  banner: TransactionalMessageBannerType
  rounded?: boolean
}

function getVisibleAnalyticsEvent(analytics: BannerAnalytics) {
  return JSON.stringify({
    category: analytics.category,
    action: 'visible',
    label: `group:${analytics.group};location:${analytics.location}`,
  })
}

function getDismissAnalyticsEvent(analytics: BannerAnalytics) {
  return JSON.stringify({
    category: analytics.category,
    action: 'dismiss',
    label: `group:${analytics.group};location:${analytics.location}`,
  })
}

// Generate a stable key for each segment based on its content
function getSegmentKey(segment: BannerSegment, index: number): string {
  return `${segment.type}-${index}-${segment.content.slice(0, 20)}`
}

export function TransactionalMessageBanner({banner, rounded}: TransactionalMessageBannerProps) {
  const [hidden, setHidden] = useState<boolean>(false)
  const bannerRef = useRef<HTMLDivElement>(null)
  const isRounded = rounded ?? banner.analytics.location !== 'global'

  // Track visible event when component mounts
  useEffect(() => {
    if (bannerRef.current) {
      bannerRef.current.setAttribute('data-analytics-visible', getVisibleAnalyticsEvent(banner.analytics))
    }
  }, [banner.analytics])

  const handleDismiss = async () => {
    try {
      await verifiedFetch(banner.dismissPath, {method: 'POST'})
    } catch {
      // Silently handle network errors to maintain a good UX
    } finally {
      setHidden(true)
    }
  }

  if (hidden) {
    return null
  }

  return (
    <div
      ref={bannerRef}
      data-hpc
      data-testid="transactional-message-banner"
      data-analytics-event={getDismissAnalyticsEvent(banner.analytics)}
    >
      <Banner
        title="Important update"
        hideTitle
        icon={<InfoIcon />}
        className={isRounded ? undefined : styles.squareBanner}
        description={
          <span className="text-normal">
            {banner.segments.map((segment, index) =>
              segment.type === 'link' ? (
                <Link key={getSegmentKey(segment, index)} inline href={segment.href}>
                  {segment.content}
                </Link>
              ) : (
                <span key={getSegmentKey(segment, index)}>{segment.content}</span>
              ),
            )}
          </span>
        }
        onDismiss={handleDismiss}
      />
    </div>
  )
}
